package io.metersphere.agent.controller;import io.metersphere.agent.dto.*;import io.metersphere.agent.service.AgentPageObjectService;import io.metersphere.sdk.constants.PermissionConstants;import jakarta.annotation.Resource;import jakarta.validation.Valid;import org.apache.shiro.authz.annotation.RequiresPermissions;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping({"/ai/page-objects","/api/ai/page-objects"}) public class AgentPageObjectController {@Resource private AgentPageObjectService service;@GetMapping @RequiresPermissions(PermissionConstants.AI_EXECUTION_READ) public List<AgentPageObjectDTO> list(@RequestParam String projectId){return service.list(projectId);}@GetMapping("/{id}") @RequiresPermissions(PermissionConstants.AI_EXECUTION_READ) public AgentPageObjectDTO get(@PathVariable String id){return service.get(id);}@PostMapping @RequiresPermissions(PermissionConstants.AI_EXECUTION_RUN) public AgentPageObjectDTO create(@RequestBody @Valid AgentPageObjectRequest r){return service.create(r);}@PutMapping("/{id}") @RequiresPermissions(PermissionConstants.AI_EXECUTION_RUN) public AgentPageObjectDTO update(@PathVariable String id,@RequestBody @Valid AgentPageObjectRequest r){return service.update(id,r);}}
